import{_ as t}from"./chunks/thunderly_tfsik01_pair.CYfj7MbC.js";import{_ as a,c as r,o as i,al as n}from"./chunks/framework.D8UyiDWg.js";const p=JSON.parse('{"title":"TFSIK01 Telemetry Modem","description":"","frontmatter":{},"headers":[],"relativePath":"ko/telemetry/tfsik_telemetry.md","filePath":"ko/telemetry/tfsik_telemetry.md"}'),o={name:"ko/telemetry/tfsik_telemetry.md"};function l(s,e,d,c,h,u){return i(),r("div",null,e[0]||(e[0]=[n('<h1 id="tfsik01-telemetry-modem" tabindex="-1">TFSIK01 Telemetry Modem <a class="header-anchor" href="#tfsik01-telemetry-modem" aria-label="Permalink to &quot;TFSIK01 Telemetry Modem&quot;">​</a></h1><p>The <a href="https://docs.thunderfly.cz/avionics/TFSIK01/" target="_blank" rel="noreferrer">TFSIK01</a> is a high-performance open-source telemetry modem developed by <a href="https://www.thunderfly.cz/" target="_blank" rel="noreferrer">ThunderFly</a>. It is designed to provide robust wireless communication between UAVs and ground stations. Featuring dual antenna diversity, strong interference immunity, and compatibility with MAVLink framing, it is an ideal choice for demanding UAV and robotics applications.</p><p><img src="'+t+'" alt="TFSIK01 pair with USB-C converter"></p><p>The modem is plug-and-play with flight controllers using a JST-GH UART interface and is available pre-configured for the 433, 868, and 915 MHz bands, (other non-standard frequencies available on request).</p><h2 id="구매처" tabindex="-1">구매처 <a class="header-anchor" href="#구매처" aria-label="Permalink to &quot;구매처&quot;">​</a></h2><ul><li><a href="https://www.tindie.com/products/thunderfly/tfsik01-high-performance-uav-telemetry-modem/" target="_blank" rel="noreferrer">TFSIK01A on Tindie</a></li><li>Directly from <a href="https://www.thunderfly.cz/contact-us.html" target="_blank" rel="noreferrer">ThunderFly</a> (<a href="mailto:sale@thunderfly.cz" target="_blank" rel="noreferrer">sale@thunderfly.cz</a>)</li></ul><h2 id="특징" tabindex="-1">특징 <a class="header-anchor" href="#특징" aria-label="Permalink to &quot;특징&quot;">​</a></h2><ul><li>Open-source SiK firmware</li><li>Dual antenna diversity with automatic switching</li><li>Robust against interference and out-of-band signal jamming</li><li>Frequency-Hopping Spread Spectrum (FHSS)</li><li>Adaptive TDM, LBT, and AFA support</li><li>MAVLink protocol support</li><li>Up to 250 kbps air data rate</li><li>Several kilometres of range</li><li>Plug-n-play with Pixhawk-compatible flight controllers</li></ul><h2 id="사양" tabindex="-1">사양 <a class="header-anchor" href="#사양" aria-label="Permalink to &quot;사양&quot;">​</a></h2><ul><li>Frequency: 433 MHz (default), 868 MHz, 915 MHz, or custom</li><li>Power: up to 500 mW (27 dBm), adjustable (100mW default)</li><li>Interface: JST-GH 6-pin UART (3.3V)</li><li>Connectors: Dual MCX — snap-on connectors that reduce the risk of damage in case of crash impacts</li><li>Weight: 18 g</li></ul><h2 id="leds-indicators-status" tabindex="-1">LEDs Indicators Status <a class="header-anchor" href="#leds-indicators-status" aria-label="Permalink to &quot;LEDs Indicators Status&quot;">​</a></h2><ul><li><strong>Green blinking</strong> – searching for link</li><li><strong>Green solid</strong> – link established</li><li><strong>Red flashing</strong> – data transmission</li><li><strong>Red solid</strong> – firmware update mode</li><li><strong>Orange</strong> – indicates selected antenna for RX/TX</li></ul><h2 id="connecting-to-flight-controller" tabindex="-1">Connecting to Flight Controller <a class="header-anchor" href="#connecting-to-flight-controller" aria-label="Permalink to &quot;Connecting to Flight Controller&quot;">​</a></h2><p>Connect to the <code>TELEM1</code> port of your flight controller using the included JST-GH cable. Configuration may be required for alternative UART ports.</p><h2 id="connecting-to-pc-or-ground-station" tabindex="-1">Connecting to PC or Ground Station <a class="header-anchor" href="#connecting-to-pc-or-ground-station" aria-label="Permalink to &quot;Connecting to PC or Ground Station&quot;">​</a></h2><p>Use the <a href="https://docs.thunderfly.cz/avionics/TFUSBSERIAL01/" target="_blank" rel="noreferrer">TFUSBSERIAL01</a> USB-C to UART adapter to connect the modem to your PC, tablet, or Raspberry Pi.</p><h2 id="package-includes" tabindex="-1">Package Includes <a class="header-anchor" href="#package-includes" aria-label="Permalink to &quot;Package Includes&quot;">​</a></h2><ul><li>2× TFSIK01 Modems (with housing)</li><li>2× JST-GH serial cables</li><li>1× TFUSBSERIAL01 USB-C to UART converter</li><li>2× MCX Antenna kit (optional)</li></ul><h2 id="추가-정보" tabindex="-1">추가 정보 <a class="header-anchor" href="#추가-정보" aria-label="Permalink to &quot;추가 정보&quot;">​</a></h2><p>For detailed specifications, configuration options, firmware updates, and advanced usage, visit the full <a href="https://docs.thunderfly.cz/avionics/TFSIK01/" target="_blank" rel="noreferrer">TFSIK01 documentation</a></p>',20)]))}const g=a(o,[["render",l]]);export{p as __pageData,g as default};
